def reservoir_seed(stream, k, seed):
    import random
    if k < 0:
        return []
    random.seed(seed)
    reservoir = []
    for i, item in enumerate(stream):
        if i < k:
            reservoir.append(item)
        else:
            r = random.randrange(i + 1)
            if r < k:
                reservoir[r] = item
    return reservoir
